:root {
  --circle-border: #01524F;

  --circle-fill-light: #EDF7F5;
  --circle-fill-middle: #D3E8E2;
  --circle-fill-base: #BDDBD4;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  border: none;

  background: transparent !important;
  pointer-events: none;
}

.circle-widget,
.circle-widget * {
  box-sizing: border-box;
}

.circle-widget {
  position: relative;
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;

  background: transparent;
  opacity: var(--w-opacity, 1);
  pointer-events: none;
}

.circle-button {
  position: absolute;
  left: 50%;
  top: 50%;

  /* Mantiene el círculo al cambiar el tamaño del widget. */
  width: 100vmin;
  height: 100vmin;
  min-width: 0;
  min-height: 0;
  margin: 0;
  padding: 0;

  transform: translate(-50%, -50%);

  appearance: none;
  border: none;
  border-radius: 50%;
  background: transparent;
  overflow: hidden;

  /* Área interactiva circular dentro del widget. */
  clip-path: circle(50% at 50% 50%);
  pointer-events: auto;

  cursor: pointer;
  user-select: none;
  touch-action: manipulation;
  -webkit-tap-highlight-color: transparent;
}

.circle-button::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 50%;
  pointer-events: none;

  box-shadow:
    inset 0 -2px 4px rgba(1, 82, 79, 0.14);

  transition: box-shadow 120ms ease;
}

.circle-svg {
  display: block;
  width: 100%;
  height: 100%;
  overflow: hidden;

  background: transparent;
  shape-rendering: geometricPrecision;
  pointer-events: none;
}

.circle-drawing {
  transform-box: view-box;
  transform-origin: 50% 50%;
  transform: scale(1);
}

.circle-fill-light {
  stop-color: var(--circle-fill-light);
}

.circle-fill-middle {
  stop-color: var(--circle-fill-middle);
}

.circle-fill-base {
  stop-color: var(--circle-fill-base);
}

.circle-fill-light,
.circle-fill-middle,
.circle-fill-base {
  transition: stop-color 120ms ease;
}

.circle-body {
  fill: url("#circle-surface");
  stroke: var(--circle-border);
  stroke-width: 3;
}

.circle-highlight {
  fill: none;
  stroke: #FFFFFF;
  stroke-width: 1.3;
  stroke-linecap: round;
  opacity: 0.65;

  transition: opacity 120ms ease;
}

@media (hover: hover) {
  .circle-button:hover {
    --circle-fill-light: #F5FCFA;
    --circle-fill-middle: #DDEFE9;
    --circle-fill-base: #C8E3DB;
  }

  .circle-button:hover .circle-highlight {
    opacity: 0.85;
  }
}

/* Hundimiento desde el centro, sin desplazamiento vertical. */
.circle-button:active {
  --circle-fill-light: #D5E8E2;
  --circle-fill-middle: #C9E1D9;
  --circle-fill-base: #B9D8CE;
}

.circle-button:active .circle-drawing {
  transform: scale(0.98);
}

.circle-button:active::after {
  box-shadow:
    inset 0 3px 6px rgba(1, 82, 79, 0.28),
    inset 0 -1px 2px rgba(255, 255, 255, 0.40);
}

.circle-button:active .circle-highlight {
  opacity: 0.25;
}

.circle-button:focus-visible {
  outline: 2px solid #FFFFFF;
  outline-offset: -5px;
}

@media (prefers-reduced-motion: reduce) {
  .circle-button::after,
  .circle-fill-light,
  .circle-fill-middle,
  .circle-fill-base,
  .circle-highlight {
    transition: none;
  }
}

