"use strict";

(function () {
  let button = null;
  let latestWidget = window.WIDGET || {};

  function render(widget) {
    if (!button) {
      return;
    }

    const name =
      typeof widget.name === "string"
        ? widget.name.trim()
        : "";

    // El nombre se utiliza únicamente como etiqueta accesible.
    button.setAttribute(
      "aria-label",
      name || "Botón circular"
    );
  }

  window.onWidgetUpdate = function (widget) {
    latestWidget = widget || {};
    render(latestWidget);
  };

  function initialize() {
    button = document.querySelector(".circle-button");
    render(latestWidget);
  }

  if (document.readyState === "loading") {
    document.addEventListener(
      "DOMContentLoaded",
      initialize,
      { once: true }
    );
  } else {
    initialize();
  }

  /*
   * Sin texto visible ni variables del PLC.
   * Hover y pulsación gestionados mediante CSS.
   * No se configura ninguna acción de control al hacer clic.
   */
})();
